window.TXB=window.TXB||{};TXB["svd/Pro"]={"12:8":"بحسب فطنته يحمد الإنسان, أما الملتوي القلب فيكون للهوان.","12:9":"الحقير وله عبد خير من المتمجد ويعوزه الخبز.","12:10":"الصديق يراعي نفس بهيمته, أما مراحم الأشرار فقاسية.","12:11":"من يشتغل بحقله يشبع خبزا, أما تابع البطالين فهو عديم الفهم.","12:12":"اشتهى الشرير صيد الأشرار, وأصل الصديقين يجدي.","12:13":"في معصية الشفتين شرك الشرير, أما الصديق فيخرج من الضيق.","12:14":"الإنسان يشبع خيرا من ثمر فمه, ومكافأة يدي الإنسان ترد له.","12:15":"طريق الجاهل مستقيم في عينيه, أما سامع المشورة فهو حكيم.","12:16":"غضب الجاهل يعرف في يومه, أما ساتر الهوان فهو ذكي.","12:17":"من يتفوه بالحق يظهر العدل, والشاهد الكاذب يظهر غشا.","12:18":"يوجد من يهذر مثل طعن السيف, أما لسان الحكماء فشفاء.","12:19":"شفة الصدق تثبت إلى الأبد, ولسان الكذب إنما هو إلى طرفة العين.","12:20":"الغش في قلب الذين يفكرون في الشر, أما المشيرون بالسلام فلهم فرح.","12:21":"لا يصيب الصديق شر, أما الأشرار فيمتلئون سوءا.","12:22":"كراهة الرب شفتا كذب, أما العاملون بالصدق فرضاه.","12:23":"الرجل الذكي يستر المعرفة, وقلب الجاهل ينادي بالحمق.","12:24":"يد المجتهدين تسود, أما الرخوة فتكون تحت الجزية.","12:25":"الغم في قلب الرجل يحنيه, والكلمة الطيبة تفرحه.","12:26":"الصديق يهدي صاحبه, أما طريق الأشرار فتضلهم.","12:27":"الرخاوة لا تمسك صيدا, أما ثروة الإنسان الكريمة فهي الاجتهاد.","12:28":"في سبيل البر حياة, وفي طريق مسلكه لا موت.","13:1":"الابن الحكيم يقبل تأديب أبيه, والمستهزئ لا يسمع انتهارا.","13:2":"من ثمرة فمه يأكل الإنسان خيرا, ومرام الغادرين ظلم.","13:3":"من يحفظ فمه يحفظ نفسه. من يفغر شفتيه فله هلاك.","13:4":"نفس الكسلان تشتهي ولا شيء لها, ونفس المجتهدين تسمن.","13:5":"الصديق يبغض كلام كذب, والشرير يخزي ويخجل.","13:6":"البر يحفظ الكامل طريقه, والشر يقلب الخاطئ.","13:7":"يوجد من يتغانى ولا شيء عنده, ومن يتفاقر وعنده غنى جزيل.","13:8":"فدية نفس رجل غناه, أما الفقير فلا يسمع انتهارا.","13:9":"نور الصديقين يفرح, وسراج الأشرار ينطفئ.","13:10":"الخصام إنما يصير بالكبرياء, ومع المتشاورين حكمة.","13:11":"غنى البطل يقل, والجامع بيده يزداد.","13:12":"الرجاء المماطل يمرض القلب, والشهوة المتممة شجرة حياة.","13:13":"من ازدرى بالكلمة يخرب نفسه, ومن خشي الوصية يكافأ.","13:14":"شريعة الحكيم ينبوع حياة للحيدان عن أشراك الموت.","13:15":"الفطنة الجيدة تمنح نعمة, أما طريق الغادرين فأوعر.","13:16":"كل ذكي يعمل بالمعرفة, والجاهل ينشر حمقا.","13:17":"الرسول الشرير يقع في الشر, والسفير الأمين شفاء.","13:18":"قفر وهوان لمن يرفض التأديب ومن يلاحظ التوبيخ يكرم.","13:19":"الشهوة الحاصلة تلذ النفس, أما كراهة الجهال فهي الحيدان عن الشر.","13:20":"المساير الحكماء يصير حكيما, ورفيق الجهال يضر.","13:21":"الشر يتبع الخاطئين, والصديقون يجازون خيرا.","13:22":"الصالح يورث بني البنين, وثروة الخاطئ تذخر للصديق.","13:23":"في حرث الفقراء طعام كثير, ويوجد هالك من عدم الحق.","13:24":"من يمنع عصاه يمقت ابنه, ومن أحبه يطلب له التأديب.","13:25":"الصديق يأكل لشبع نفسه, أما بطن الأشرار فيحتاج.","14:1":"حكمة المرأة تبني بيتها, والحماقة تهدمه بيدها.","14:2":"السالك باستقامته يتقي الرب, والمعوج طرقه يحتقره.","14:3":"في فم الجاهل قضيب لكبريائه, أما شفاه الحكماء فتحفظهم.","14:4":"حيث لا بقر فالمعلف فارغ, وكثرة الغلة بقوة الثور.","14:5":"الشاهد الأمين لن يكذب, والشاهد الزور يتفوه بالأكاذيب.","14:6":"المستهزئ يطلب الحكمة ولا يجدها, والمعرفة هينة للفهيم.","14:7":"اذهب من قدام رجل جاهل إذ لا تشعر بشفتي معرفة.","14:8":"حكمة الذكي فهم طريقه, وغباوة الجهال غش.","14:9":"الجهال يستهزئون بالإثم, وبين المستقيمين رضى.","14:10":"القلب يعرف مرارة نفسه, وبفرحه لا يشاركه غريب.","14:11":"بيت الأشرار يخرب, وخيمة المستقيمين تزهر.","14:12":"توجد طريق تظهر للإنسان مستقيمة, وعاقبتها طرق الموت.","14:13":"أيضا في الضحك يكتئب القلب, وعاقبة الفرح حزن.","14:14":"المرتد في القلب يشبع من طرقه, والرجل الصالح مما عنده.","14:15":"الغبي يصدق كل كلمة, والذكي ينتبه إلى خطواته.","14:16":"الحكيم يخشى ويحيد عن الشر, والجاهل يتصلف ويثق.","14:17":"السريع الغضب يعمل بالحمق, وذو المكايد يشنأ.","14:18":"الأغبياء يرثون الحماقة, والأذكياء يتوجون بالمعرفة.","14:19":"الأشرار ينحنون أمام الأخيار, والأثمة لدى أبواب الصديق.","14:20":"أيضا من قريبه يبغض الفقير, ومحبو الغني كثيرون.","14:21":"من يحتقر قريبه يخطئ, ومن يرحم المساكين فطوبى له.","14:22":"أما يضل مخترعو الشر أما الرحمة والحق فيهديان مخترعي الخير.","14:23":"في كل تعب منفعة, وكلام الشفتين إنما هو إلى الفقر.","14:24":"تاج الحكماء غناهم. تقدم الجهال حماقة.","14:25":"الشاهد الأمين منجي النفوس, ومن يتفوه بالأكاذيب فغش.","14:26":"في مخافة الرب ثقة شديدة, ويكون لبنيه ملجأ.","14:27":"مخافة الرب ينبوع حياة للحيدان عن أشراك الموت.","14:28":"في كثرة الشعب زينة الملك, وفي عدم القوم هلاك الأمير.","14:29":"بطيء الغضب كثير الفهم, وقصير الروح معلي الحمق.","14:30":"حياة الجسد هدوء القلب, ونخر العظام الحسد.","14:31":"ظالم الفقير يعير خالقه, ويمجده راحم المسكين.","14:32":"الشرير يطرد بشره, أما الصديق فواثق عند موته.","14:33":"في قلب الفهيم تستقر الحكمة, وما في داخل الجهال يعرف.","14:34":"البر يرفع شأن الأمة, وعار الشعوب الخطية.","14:35":"رضوان الملك على العبد الفطن, وسخطه يكون على المخزي.","15:1":"الجواب اللين يصرف الغضب, والكلام الموجع يهيج السخط.","15:2":"لسان الحكماء يحسن المعرفة, وفم الجهال ينبع حماقة.","15:3":"في كل مكان عينا الرب مراقبتين الطالحين والصالحين.","15:4":"هدوء اللسان شجرة حياة, واعوجاجه سحق في الروح.","15:5":"الأحمق يستهين بتأديب أبيه, أما مراعي التوبيخ فيذكى.","15:6":"في بيت الصديق كنز عظيم, وفي دخل الأشرار كدر.","15:7":"شفاه الحكماء تذر معرفة, أما قلب الجهال فليس كذلك.","15:8":"ذبيحة الأشرار مكرهة الرب, وصلاة المستقيمين مرضاته.","15:9":"مكرهة الرب طريق الشرير, وتابع البر يحبه.","15:10":"تأديب شر لتارك الطريق. مبغض التوبيخ يموت.","15:11":"الهاوية والهلاك أمام الرب. كم بالحري قلوب بني آدم!","15:12":"المستهزئ لا يحب موبخه. إلى الحكماء لا يذهب.","15:13":"القلب الفرحان يجعل الوجه طلقا, وبحزن القلب تنسحق الروح.","15:14":"قلب الفهيم يطلب معرفة, وفم الجهال يرعى حماقة.","15:15":"كل أيام الحزين شقية, أما طيب القلب فوليمة دائمة.","15:16":"القليل مع مخافة الرب, خير من كنز عظيم مع هم.","15:17":"أكلة من البقول حيث تكون المحبة, خير من ثور معلوف ومعه بغضة.","15:18":"الرجل الغضوب يهيج الخصومة, وبطيء الغضب يسكن الخصام.","15:19":"طريق الكسلان كسياج من شوك, وطريق المستقيمين منهج.","15:20":"الابن الحكيم يسر أباه, والرجل الجاهل يحتقر أمه.","15:21":"الحماقة فرح لناقص الفهم, أما ذو الفهم فيقوم سلوكه.","15:22":"مقاصد بغير مشورة تبطل, وبكثرة المشيرين تقوم.","15:23":"للإنسان فرح بجواب فمه, والكلمة في وقتها ما أحسنها.","15:24":"طريق الحياة للفطن إلى فوق, للحيدان عن الهاوية من تحت.","15:25":"الرب يقلع بيت المتكبرين, ويوطد تخم الأرملة.","15:26":"مكرهة الرب أفكار الشرير, وللأطهار كلام حسن.","15:27":"المولع بالكسب يكدر بيته, والكاره الهدايا يعيش.","15:28":"قلب الصديق يتفكر بالجواب, وفم الأشرار ينبع شرورا.","15:29":"الرب بعيد عن الأشرار, ويسمع صلاة الصديقين.","15:30":"نور العينين يفرح القلب. الخبر الطيب يسمن العظام.","15:31":"الأذن السامعة توبيخ الحياة تستقر بين الحكماء.","15:32":"من يرفض التأديب يرذل نفسه, ومن يسمع للتوبيخ يقتني فهما.","15:33":"مخافة الرب أدب حكمة, وقبل الكرامة التواضع.","16:1":"للإنسان تدابير القلب, ومن الرب جواب اللسان.","16:2":"كل طرق الإنسان نقية في عيني نفسه, والرب وازن الأرواح.","16:3":"ألق على الرب أعمالك فتثبت أفكارك.","16:4":"الرب صنع الكل لغرضه, والشرير أيضا ليوم الشر.","16:5":"مكرهة الرب كل متشامخ القلب. يدا ليد لا يتبرأ.","16:6":"بالرحمة والحق يستر الإثم, وفي مخافة الرب الحيدان عن الشر.","16:7":"إذا أرضت الرب طرق إنسان, جعل أعداءه أيضا يسالمونه.","16:8":"القليل مع العدل خير من دخل جزيل بغير حق.","16:9":"قلب الإنسان يفكر في طريقه, والرب يهدي خطوته.","1:1":"أمثال سليمان بن داود ملك إسرائيل:","1:2":"لمعرفة حكمة وأدب لإدراك أقوال الفهم.","1:3":"لقبول تأديب المعرفة والعدل والحق والاستقامة.","1:4":"لتعطي الجهال ذكاء, والشاب معرفة وتدبرا.","1:5":"يسمعها الحكيم فيزداد علما, والفهيم يكتسب تدبيرا.","1:6":"لفهم المثل واللغز, أقوال الحكماء وغوامضهم.","1:7":"مخافة الرب رأس المعرفة. أما الجاهلون فيحتقرون الحكمة والأدب.","1:8":"اسمع يا ابني تأديب أبيك, ولا ترفض شريعة أمك","1:9":"لأنهما إكليل نعمة لرأسك, وقلائد لعنقك.","1:10":"يا ابني, إن تملقك الخطاة فلا ترض.","1:11":"إن قالوا: «هلم معنا لنكمن للدم. لنختف للبريء باطلا.","1:12":"لنبتلعهم أحياء كالهاوية, وصحاحا كالهابطين في الجب","1:13":"فنجد كل قنية فاخرة, نملأ بيوتنا غنيمة.","1:14":"تلقي قرعتك وسطنا. يكون لنا جميعا كيس واحد».","1:15":"يا ابني, لا تسلك في الطريق معهم. امنع رجلك عن مسالكهم.","1:16":"لأن أرجلهم تجري إلى الشر وتسرع إلى سفك الدم.","1:17":"لأنه باطلا تنصب الشبكة في عيني كل ذي جناح.","1:18":"أما هم فيكمنون لدم أنفسهم. يختفون لأنفسهم.","1:19":"هكذا طرق كل مولع بكسب. يأخذ نفس مقتنيه!","1:20":"الحكمة تنادي في الخارج. في الشوارع تعطي صوتها.","1:21":"تدعو في رؤوس الأسواق, في مداخل الأبواب. في المدينة تبدي كلامها","1:22":"قائلة: «إلى متى أيها الجهال تحبون الجهل, والمستهزئون يسرون بالاستهزاء, والحمقى يبغضون العلم؟","1:23":"ارجعوا عند توبيخي. هئنذا أفيض لكم روحي. أعلمكم كلماتي.","1:24":"«لأني دعوت فأبيتم, ومددت يدي وليس من يبالي","1:25":"بل رفضتم كل مشورتي, ولم ترضوا توبيخي.","1:26":"فأنا أيضا أضحك عند بليتكم. أشمت عند مجيء خوفكم.","1:27":"إذا جاء خوفكم كعاصفة, وأتت بليتكم كالزوبعة, إذا جاءت عليكم شدة وضيق","1:28":"حينئذ يدعونني فلا أستجيب. يبكرون إلي فلا يجدونني.","1:29":"لأنهم أبغضوا العلم ولم يختاروا مخافة الرب.","1:30":"لم يرضوا مشورتي. رذلوا كل توبيخي.","1:31":"فلذلك يأكلون من ثمر طريقهم, ويشبعون من مؤامراتهم.","1:32":"لأن ارتداد الحمقى يقتلهم, وراحة الجهال تبيدهم.","1:33":"أما المستمع لي فيسكن آمنا, ويستريح من خوف الشر».","2:1":"يا ابني, إن قبلت كلامي وخبأت وصاياي عندك","2:2":"حتى تميل أذنك إلى الحكمة, وتعطف قلبك على الفهم -","2:3":"إن دعوت المعرفة, ورفعت صوتك إلى الفهم","2:4":"إن طلبتها كالفضة, وبحثت عنها كالكنوز","2:5":"فحينئذ تفهم مخافة الرب, وتجد معرفة الله.","2:6":"لأن الرب يعطي حكمة. من فمه المعرفة والفهم.","2:7":"يذخر معونة للمستقيمين. هو مجن للسالكين بالكمال","2:8":"لنصر مسالك الحق وحفظ طريق أتقيائه.","2:9":"حينئذ تفهم العدل والحق والاستقامة: كل سبيل صالح.","2:10":"إذا دخلت الحكمة قلبك, ولذت المعرفة لنفسك","2:11":"فالعقل يحفظك, والفهم ينصرك","2:12":"لإنقاذك من طريق الشرير, ومن الإنسان المتكلم بالأكاذيب","2:13":"التاركين سبل الاستقامة للسلوك في مسالك الظلمة","2:14":"الفرحين بفعل السوء, المبتهجين بأكاذيب الشر","2:15":"الذين طرقهم معوجة, وهم ملتوون في سبلهم.","2:16":"لإنقاذك من المرأة الأجنبية, من الغريبة المتملقة بكلامها","2:17":"التاركة أليف صباها, والناسية عهد إلهها.","2:18":"لأن بيتها يسوخ إلى الموت, وسبلها إلى الأخيلة.","2:19":"كل من دخل إليها لا يرجع ولا يبلغون سبل الحياة.","2:20":"حتى تسلك في طريق الصالحين وتحفظ سبل الصديقين.","2:21":"لأن المستقيمين يسكنون الأرض, والكاملين يبقون فيها.","2:22":"أما الأشرار فينقرضون من الأرض, والغادرون يستأصلون منها.","3:1":"يا ابني, لا تنس شريعتي, بل ليحفظ قلبك وصاياي.","3:2":"فإنها تزيدك طول أيام, وسني حياة وسلامة.","3:3":"لا تدع الرحمة والحق يتركانك. تقلدهما على عنقك. اكتبهما على لوح قلبك","3:4":"فتجد نعمة وفطنة صالحة في أعين الله والناس.","3:5":"توكل على الرب بكل قلبك, وعلى فهمك لا تعتمد.","3:6":"في كل طرقك اعرفه, وهو يقوم سبلك.","3:7":"لا تكن حكيما في عيني نفسك. اتق الرب وابعد عن الشر","3:8":"فيكون شفاء لسرتك, وسقاء لعظامك.","3:9":"أكرم الرب من مالك ومن كل باكورات غلتك","3:10":"فتمتلئ خزائنك شبعا, وتفيض معاصرك مسطارا.","3:11":"يا ابني, لا تحتقر تأديب الرب ولا تكره توبيخه","3:12":"لأن الذي يحبه الرب يؤدبه, وكأب بابن يسر به.","3:13":"طوبى للإنسان الذي يجد الحكمة, وللرجل الذي ينال الفهم","3:14":"لأن تجارتها خير من تجارة الفضة, وربحها خير من الذهب الخالص.","3:15":"هي أثمن من اللآلئ, وكل جواهرك لا تساويها.","3:16":"في يمينها طول أيام, وفي يسارها الغنى والمجد.","3:17":"طرقها طرق نعم, وكل مسالكها سلام.","3:18":"هي شجرة حياة لممسكيها, والمتمسك بها مغبوط.","3:19":"الرب بالحكمة أسس الأرض. أثبت السماوات بالفهم.","3:20":"بعلمه انشقت اللجج, وتقطر السحاب ندى.","3:21":"يا ابني, لا تبرح هذه من عينيك. احفظ الرأي والتدبير","3:22":"فيكونا حياة لنفسك, ونعمة لعنقك.","3:23":"حينئذ تسلك في طريقك آمنا, ولا تعثر رجلك.","3:24":"إذا اضطجعت فلا تخاف, بل تضطجع ويلذ نومك.","3:25":"لا تخشى من خوف باغت, ولا من خراب الأشرار إذا جاء.","3:26":"لأن الرب يكون معتمدك, ويصون رجلك من أن تؤخذ.","3:27":"لا تمنع الخير عن أهله, حين يكون في طاقة يدك أن تفعله.","3:28":"لا تقل لصاحبك: «اذهب وعد فأعطيك غدا» وموجود عندك.","3:29":"لا تخترع شرا على صاحبك, وهو ساكن لديك آمنا.","3:30":"لا تخاصم إنسانا بدون سبب, إن لم يكن قد صنع معك شرا.","3:31":"لا تحسد الظالم ولا تختر شيئا من طرقه","3:32":"لأن الملتوي رجس عند الرب. أما سره فعند المستقيمين.","3:33":"لعنة الرب في بيت الشرير, لكنه يبارك مسكن الصديقين.","3:34":"كما أنه يستهزئ بالمستهزئين, هكذا يعطي نعمة للمتواضعين.","3:35":"الحكماء يرثون مجدا والحمقى يحملون هوانا.","4:1":"اسمعوا أيها البنون تأديب الأب, واصغوا لأجل معرفة الفهم","4:2":"لأني أعطيكم تعليما صالحا, فلا تتركوا شريعتي.","4:3":"فإني كنت ابنا لأبي, غضا ووحيدا عند أمي","4:4":"وكان يريني ويقول لي: «ليضبط قلبك كلامي. احفظ وصاياي فتحيا.","4:5":"اقتن الحكمة. اقتن الفهم. لا تنس ولا تعرض عن كلمات فمي.","4:6":"لا تتركها فتحفظك. أحببها فتصونك.","4:7":"الحكمة هي الرأس فاقتن الحكمة, وبكل مقتناك اقتن الفهم.","4:8":"ارفعها فتعليك. تمجدك إذا اعتنقتها.","4:9":"تعطي رأسك إكليل نعمة. تاج جمال تمنحك».","4:10":"اسمع يا ابني واقبل أقوالي, فتكثر سنو حياتك.","4:11":"أريتك طريق الحكمة. هديتك سبل الاستقامة.","4:12":"إذا سرت فلا تضيق خطواتك, وإذا سعيت فلا تعثر.","4:13":"تمسك بالأدب. لا ترخه. احفظه فإنه هو حياتك.","4:14":"لا تدخل في سبيل الأشرار, ولا تسر في طريق الأثمة.","4:15":"تنكب عنه. لا تمر به. حد عنه واعبر","4:16":"لأنهم لا ينامون إن لم يفعلوا سوءا, وينزع نومهم إن لم يسقطوا أحدا.","4:17":"لأنهم يطعمون خبز الشر, ويشربون خمر الظلم.","4:18":"أما سبيل الصديقين فكنور مشرق, يتزايد وينير إلى النهار الكامل.","4:19":"أما طريق الأشرار فكالظلام. لا يعلمون ما يعثرون به.","4:20":"يا ابني, أصغ إلى كلامي. أمل أذنك إلى أقوالي.","4:21":"لا تبرح عن عينيك. احفظها في وسط قلبك.","4:22":"لأنها هي حياة للذين يجدونها, ودواء لكل الجسد.","4:23":"فوق كل تحفظ احفظ قلبك, لأن منه مخارج الحياة.","4:24":"انزع عنك التواء الفم, وأبعد عنك انحراف الشفتين.","4:25":"لتنظر عيناك إلى قدامك, وأجفانك إلى أمامك مستقيما.","4:26":"مهد سبيل رجلك, فتثبت كل طرقك.","4:27":"لا تمل يمنة ولا يسرة. باعد رجلك عن الشر.","5:1":"يا ابني, أصغ إلى حكمتي. أمل أذنك إلى فهمي","5:2":"لحفظ التدابير, ولتحفظ شفتاك معرفة.","5:3":"لأن شفتي المرأة الأجنبية تقطران عسلا, وحنكها أنعم من الزيت.","5:4":"لكن عاقبتها مرة كالأفسنتين. حادة كسيف ذي حدين.","5:5":"قدماها تنحدران إلى الموت. خطواتها تتمسك بالهاوية.","5:6":"لئلا تتأمل طريق الحياة. تمايلت خطواتها ولا تشعر.","5:7":"والآن أيها البنون اسمعوا لي, ولا ترتدوا عن كلمات فمي.","5:8":"أبعد طريقك عنها, ولا تقرب إلى باب بيتها","5:9":"لئلا تعطي زهرك لآخرين, وسنينك للقاسي.","5:10":"لئلا تشبع الأجانب من قوتك, وتكون أتعابك في بيت غريب.","5:11":"فتنوح في أواخرك, عند فناء لحمك وجسمك","5:12":"فتقول: «كيف أني أبغضت الأدب ورذل قلبي التوبيخ!","5:13":"ولم أسمع لصوت مرشدي, ولم أمل أذني إلى معلمي.","5:14":"لولا قليل لكنت في كل شر, في وسط الزمرة والجماعة».","5:15":"اشرب مياها من جبك, ومياها جارية من بئرك.","5:16":"لا تفض ينابيعك إلى الخارج, سواقي مياه في الشوارع.","5:17":"لتكن لك وحدك, وليس لأجانب معك.","5:18":"ليكن ينبوعك مباركا, وافرح بامرأة شبابك","5:19":"الظبية المحبوبة والوعلة الزهية. ليروك ثدياها في كل وقت, وبمحبتها اسكر دائما.","5:20":"فلماذا تفتن يا ابني بأجنبية وتحتضن غريبة","5:21":"لأن طرق الإنسان أمام عيني الرب, وهو يزن كل سبله.","5:22":"الشرير تأخذه آثامه وبحبال خطيته يمسك.","5:23":"إنه يموت من عدم الأدب, وبفرط حمقه يتهور.","6:1":"يا ابني, إن ضمنت صاحبك, إن صفقت كفك لغريب","6:2":"إن علقت في كلام فمك, إن أخذت بكلام فيك.","6:3":"إذا فافعل هذا يا ابني, ونج نفسك إذا صرت في يد صاحبك: اذهب ترام وألح على صاحبك.","6:4":"لا تعط عينيك نوما, ولا أجفانك نعاسا.","6:5":"نج نفسك كالظبي من اليد, كالعصفور من يد الصياد.","6:6":"اذهب إلى النملة أيها الكسلان. تأمل طرقها وكن حكيما.","6:7":"التي ليس لها قائد أو عريف أو متسلط","6:8":"وتعد في الصيف طعامها, وتجمع في الحصاد أكلها.","6:9":"إلى متى تنام أيها الكسلان؟ متى تنهض من نومك؟","6:10":"قليل نوم بعد قليل نعاس, وطي اليدين قليلا للرقود","6:11":"فيأتي فقرك كساع وعوزك كغاز!","6:12":"الرجل اللئيم, الرجل الأثيم يسعى باعوجاج الفم.","6:13":"يغمز بعينيه. يقول برجله. يشير بأصابعه.","6:14":"في قلبه أكاذيب. يخترع الشر في كل حين. يزرع خصومات.","6:15":"لأجل ذلك بغتة تفاجئه بليته. في لحظة ينكسر ولا شفاء.","6:16":"هذه الستة يبغضها الرب, وسبعة هي مكرهة نفسه:","6:17":"عيون متعالية, لسان كاذب, أيد سافكة دما بريئا","6:18":"قلب ينشئ أفكارا رديئة, أرجل سريعة الجريان إلى السوء","6:19":"شاهد زور يفوه بالأكاذيب, وزارع خصومات بين إخوة.","6:20":"يا ابني, احفظ وصايا أبيك ولا تترك شريعة أمك.","6:21":"اربطها على قلبك دائما. قلد بها عنقك.","6:22":"إذا ذهبت تهديك. إذا نمت تحرسك, وإذا استيقظت فهي تحدثك.","6:23":"لأن الوصية مصباح, والشريعة نور, وتوبيخات الأدب طريق الحياة.","6:24":"لحفظك من المرأة الشريرة, من ملق لسان الأجنبية.","6:25":"لا تشتهين جمالها بقلبك, ولا تأخذك بهدبها.","6:26":"لأنه بسبب امرأة زانية يفتقر المرء إلى رغيف خبز, وامرأة رجل آخر تقتنص النفس الكريمة.","6:27":"أيأخذ إنسان نارا في حضنه ولا تحترق ثيابه؟","6:28":"أو يمشي إنسان على الجمر ولا تكتوي رجلاه؟","6:29":"هكذا من يدخل على امرأة صاحبه. كل من يمسها لا يكون بريئا.","6:30":"لا يستخفون بالسارق ولو سرق ليشبع نفسه وهو جوعان.","6:31":"إن وجد يرد سبعة أضعاف, ويعطي كل قنية بيته.","6:32":"أما الزاني بامرأة فعديم العقل. المهلك نفسه هو يفعله.","6:33":"ضربا وخزيا يجد, وعاره لا يمحى.","6:34":"لأن الغيرة هي حمية الرجل, فلا يشفق في يوم الانتقام.","6:35":"لا ينظر إلى فدية ما, ولا يرضى ولو أكثرت الرشوة.","7:1":"يا ابني, احفظ كلامي واذخر وصاياي عندك.","7:2":"احفظ وصاياي فتحيا, وشريعتي كحدقة عينك.","7:3":"اربطها على أصابعك. اكتبها على لوح قلبك.","7:4":"قل للحكمة: «أنت أختي» وادع الفهم ذا قرابة.","7:5":"لتحفظك من المرأة الأجنبية, من الغريبة الملقة بكلامها.","7:6":"لأني من كوة بيتي, من وراء شباكي تطلعت","7:7":"فرأيت بين الجهال, لاحظت بين البنين غلاما عديم الفهم","7:8":"عابرا في الشارع عند زاويتها, وصاعدا في طريق بيتها.","7:9":"في العشاء, في مساء اليوم, في حدقة الليل والظلام.","7:10":"وإذا بامرأة استقبلته في زي زانية, وخبيثة القلب.","7:11":"صخابة هي وجامحة. في بيتها لا تستقر قدماها.","7:12":"تارة في الخارج, وأخرى في الشوارع. وعند كل زاوية تكمن.","7:13":"فأمسكته وقبلته. أوقحت وجهها وقالت له:","7:14":"«علي ذبائح السلامة. اليوم أوفيت نذوري.","7:15":"فلذلك خرجت للقائك, لأطلب وجهك حتى أجدك.","7:16":"بالديباج فرشت سريري, بموشى كتان من مصر.","7:17":"عطرت فراشي بمر وعود وقرفة.","7:18":"هلم نرتو ودا إلى الصباح. نتلذذ بالحب.","7:19":"لأن الرجل ليس في البيت. ذهب في طريق بعيدة.","7:20":"أخذ صرة الفضة بيده. يوم الهلال يأتي إلى بيته».","7:21":"أغوته بكثرة فنونها, بملث شفتيها طوحته.","7:22":"ذهب وراءها لوقته, كثور يذهب إلى الذبح, أو كالغبي إلى قيد القصاص","7:23":"حتى يشق سهم كبده. كطير يسرع إلى الفخ ولا يدري أنه لنفسه.","7:24":"والآن أيها الأبناء اسمعوا لي وأصغوا لكلمات فمي.","7:25":"لا يمل قلبك إلى طرقها, ولا تشرد في مسالكها.","7:26":"لأنها طرحت كثيرين جرحى, وكل قتلاها أقوياء.","7:27":"طرق الهاوية بيتها, هابطة إلى خدور الموت.","8:1":"ألعل الحكمة لا تنادي والفهم ألا يعطي صوته؟","8:2":"عند رؤوس الشواهق, عند الطريق بين المسالك تقف.","8:3":"بجانب الأبواب, عند ثغر المدينة, عند مدخل الأبواب تصرح:","8:4":"«لكم أيها الناس أنادي, وصوتي إلى بني آدم.","8:5":"أيها الحمقى تعلموا ذكاء, ويا جهال تعلموا فهما.","8:6":"اسمعوا فإني أتكلم بأمور شريفة, وافتتاح شفتي استقامة.","8:7":"لأن حنكي يلهج بالصدق, ومكرهة شفتي الكذب.","8:8":"كل كلمات فمي بالحق. ليس فيها عوج ولا التواء.","8:9":"كلها واضحة لدى الفهيم, ومستقيمة لدى الذين يجدون المعرفة.","8:10":"خذوا تأديبي لا الفضة. والمعرفة أكثر من الذهب المختار.","8:11":"لأن الحكمة خير من اللآلئ, وكل الجواهر لا تساويها.","8:12":"«أنا الحكمة أسكن الذكاء, وأجد معرفة التدابير.","8:13":"مخافة الرب بغض الشر. الكبرياء والتعظم وطريق الشر وفم الأكاذيب أبغضت.","8:14":"لي المشورة والرأي. أنا الفهم. لي القدرة.","8:15":"بي تملك الملوك, وتقضي العظماء عدلا.","8:16":"بي تترأس الرؤساء والشرفاء, كل قضاة الأرض.","8:17":"أنا أحب الذين يحبونني, والذين يبكرون إلي يجدونني.","8:18":"عندي الغنى والكرامة. قنية فاخرة وحظ.","8:19":"ثمري خير من الذهب ومن الإبريز, وغلتي خير من الفضة المختارة.","8:20":"في طريق العدل أتمشى, في وسط سبل الحق","8:21":"فأورث محبي رزقا وأملأ خزائنهم.","8:22":"«الرب قناني أول طريقه, من قبل أعماله, منذ القدم.","8:23":"منذ الأزل مسحت, منذ البدء, منذ أوائل الأرض.","8:24":"إذ لم يكن غمر أبدئت. إذ لم تكن ينابيع كثيرة المياه.","8:25":"من قبل أن تقررت الجبال, قبل التلال أبدئت.","8:26":"إذ لم يكن قد صنع الأرض بعد ولا البراري ولا أول أعفار المسكونة.","8:27":"لما ثبت السماوات كنت هناك أنا. لما رسم دائرة على وجه الغمر.","8:28":"لما أثبت السحب من فوق. لما تشددت ينابيع الغمر.","8:29":"لما وضع للبحر حده فلا تتعدى المياه تخمه, لما رسم أسس الأرض","8:30":"كنت عنده صانعا, وكنت كل يوم لذته, فرحة دائما قدامه.","8:31":"فرحة في مسكونة أرضه, ولذاتي مع بني آدم.","8:32":"«فالآن أيها البنون اسمعوا لي - فطوبى للذين يحفظون طرقي.","8:33":"اسمعوا التعليم وكونوا حكماء ولا ترفضوه.","8:34":"طوبى للإنسان الذي يسمع لي ساهرا كل يوم عند مصاريعي, حافظا قوائم أبوابي.","8:35":"لأن من يجدني يجد الحياة وينال رضى من الرب","8:36":"ومن يخطئ عني يضر نفسه. كل مبغضي يحبون الموت».","9:1":"الحكمة بنت بيتها. نحتت أعمدتها السبعة.","9:2":"ذبحت ذبحها. مزجت خمرها. أيضا رتبت مائدتها.","9:3":"أرسلت جواريها تنادي على ظهور أعالي المدينة:","9:4":"«من هو جاهل فليمل إلى هنا». والناقص الفهم قالت له:","9:5":"«هلموا كلوا من طعامي, واشربوا من الخمر التي مزجتها.","9:6":"اتركوا الجهالات فتحيوا, وسيروا في طريق الفهم.","9:7":"«من يوبخ مستهزئا يكسب لنفسه هوانا, ومن ينذر شريرا يكسب عيبا.","9:8":"لا توبخ مستهزئا لئلا يبغضك. وبخ حكيما فيحبك.","9:9":"أعط حكيما فيكون أوفر حكمة. علم صديقا فيزداد علما.","9:10":"بدء الحكمة مخافة الرب, ومعرفة القدوس فهم.","9:11":"لأنه بي تكثر أيامك وتزداد لك سنو حياة.","9:12":"إن كنت حكيما فأنت حكيم لنفسك, وإن استهزأت فأنت وحدك تتحمل».","9:13":"المرأة الجاهلة صخابة حمقاء ولا تدري شيئا","9:14":"فتقعد عند باب بيتها على كرسي في أعالي المدينة","9:15":"لتنادي عابري السبيل المقومين طرقهم:","9:16":"«من هو جاهل فليمل إلى هنا». والناقص الفهم تقول له:","9:17":"«المياه المسروقة حلوة, وخبز الخفية لذيذ».","9:18":"ولا يعلم أن الأخيلة هناك, وأن في أعماق الهاوية ضيوفها.","10:1":"أمثال سليمان - الابن الحكيم يسر أباه, والابن الجاهل حزن أمه.","10:2":"كنوز الشر لا تنفع, أما البر فينجي من الموت.","10:3":"الرب لا يجيع نفس الصديق, ولكنه يدفع هوى الأشرار.","10:4":"العامل بيد رخوة يفتقر, أما يد المجتهدين فتغني.","10:5":"من يجمع في الصيف فهو ابن عاقل, ومن ينام في الحصاد فهو ابن مخز.","10:6":"بركات على رأس الصديق, أما فم الأشرار فيغشاه ظلم.","10:7":"ذكر الصديق للبركة, واسم الأشرار ينخر.","10:8":"حكيم القلب يقبل الوصايا, وغبي الشفتين يصرع.","10:9":"من يسلك بالاستقامة يسلك بالأمان, ومن يعوج طرقه يعرف.","10:10":"من يغمز بالعين يسبب حزنا, والغبي الشفتين يصرع.","10:11":"فم الصديق ينبوع حياة, وفم الأشرار يغشاه ظلم.","10:12":"البغضة تهيج خصومات, والمحبة تستر كل الذنوب.","10:13":"في شفتي العاقل توجد حكمة, والعصا لظهر الناقص الفهم.","10:14":"الحكماء يذخرون معرفة, أما فم الغبي فهلاك قريب.","10:15":"ثروة الغني مدينته الحصينة. هلاك المساكين فقرهم.","10:16":"عمل الصديق للحياة. ربح الشرير للخطية.","10:17":"حافظ التعليم هو في طريق الحياة, ورافض التأديب ضال.","10:18":"من يخفي البغضة فشفتاه كاذبتان, ومشيع المذمة هو جاهل.","10:19":"كثرة الكلام لا تخلو من معصية, أما الضابط شفتيه فعاقل.","10:20":"لسان الصديق فضة مختارة. قلب الأشرار كشيء زهيد.","10:21":"شفتا الصديق تهديان كثيرين, أما الأغبياء فيموتون من نقص الفهم.","10:22":"بركة الرب هي تغني, ولا يزيد الرب معها تعبا.","10:23":"فعل الرذيلة عند الجاهل كالضحك, أما الحكمة فلذي فهم.","10:24":"خوف الشرير هو يأتيه, وشهوة الصديقين تمنح.","10:25":"كعبور الزوبعة فلا يكون الشرير, أما الصديق فأساس مؤبد.","10:26":"كالخل للأسنان, وكالدخان للعينين, كذلك الكسلان للذين أرسلوه.","10:27":"مخافة الرب تزيد الأيام, أما سنو الأشرار فتقصر.","10:28":"منتظر الصديقين مفرح, أما رجاء الأشرار فيبيد.","10:29":"حصن للاستقامة طريق الرب, والهلاك لفاعلي الإثم.","10:30":"الصديق لن يزحزح أبدا, والأشرار لن يسكنوا الأرض.","10:31":"فم الصديق ينبت الحكمة, أما لسان الأكاذيب فيقطع.","10:32":"شفتا الصديق تعرفان المرضي, وفم الأشرار أكاذيب.","11:1":"موازين غش مكرهة الرب, والوزن الصحيح رضاه.","11:2":"تأتي الكبرياء فيأتي الهوان, ومع المتواضعين حكمة.","11:3":"استقامة المستقيمين تهديهم, واعوجاج الغادرين يخربهم.","11:4":"لا ينفع الغنى في يوم السخط, أما البر فينجي من الموت.","11:5":"بر الكامل يقوم طريقه, أما الشرير فيسقط بشره.","11:6":"بر المستقيمين ينجيهم, أما الغادرون فيؤخذون بفسادهم.","11:7":"عند موت إنسان شرير يهلك رجاؤه, ومنتظر الأثمة يبيد.","11:8":"الصديق ينجو من الضيق, ويأتي الشرير مكانه.","11:9":"بالفم يخرب المنافق صاحبه, وبالمعرفة ينجو الصديقون.","11:10":"بخير الصديقين تفرح المدينة, وعند هلاك الأشرار هتاف.","11:11":"ببركة المستقيمين تعلو المدينة, وبفم الأشرار تهدم.","11:12":"المحتقر صاحبه هو ناقص الفهم, أما ذو الفهم فيسكت.","11:13":"الساعي بالوشاية يفشي السر, والأمين الروح يكتم الأمر.","11:14":"حيث لا تدبير يسقط الشعب, أما الخلاص فبكثرة المشيرين.","11:15":"ضررا يضر من يضمن غريبا, ومن يبغض صفق الأيدي مطمئن.","11:16":"المرأة ذات النعمة تحصل كرامة, والأشداء يحصلون غنى.","11:17":"الرجل الرحيم يحسن إلى نفسه, والقاسي يكدر لحمه.","11:18":"الشرير يكسب أجرة غش, والزارع البر أجرة أمانة.","11:19":"كما أن البر يؤول إلى الحياة كذلك من يتبع الشر فإلى موته.","11:20":"كراهة الرب ملتوو القلب, ورضاه مستقيمو الطريق.","11:21":"يد ليد لا يتبرر الشرير, أما نسل الصديقين فينجو.","11:22":"خزامة ذهب في فنطيسة خنزيرة المرأة الجميلة العديمة العقل.","11:23":"شهوة الأبرار خير فقط. رجاء الأشرار سخط.","11:24":"يوجد من يفرق فيزداد أيضا, ومن يمسك أكثر من اللائق وإنما إلى الفقر.","11:25":"النفس السخية تسمن, والمروي هو أيضا يروى.","11:26":"محتكر الحنطة يلعنه الشعب, والبركة على رأس البائع.","11:27":"من يطلب الخير يلتمس الرضا, ومن يطلب الشر فالشر يأتيه.","11:28":"من يتكل على غناه يسقط, أما الصديقون فيزهون كالورق.","11:29":"من يكدر بيته يرث الريح, والغبي خادم لحكيم القلب.","11:30":"ثمر الصديق شجرة حياة, ورابح النفوس حكيم.","11:31":"هوذا الصديق يجازى في الأرض, فكم بالحري الشرير والخاطئ!","12:1":"من يحب التأديب يحب المعرفة, ومن يبغض التوبيخ فهو بليد.","12:2":"الصالح ينال رضى من قبل الرب, أما رجل المكايد فيحكم عليه.","12:3":"لا يثبت الإنسان بالشر, أما أصل الصديقين فلا يتقلقل.","12:4":"المرأة الفاضلة تاج لبعلها, أما المخزية فكنخر في عظامه.","12:5":"أفكار الصديقين عدل. تدابير الأشرار غش.","12:6":"كلام الأشرار كمون للدم, أما فم المستقيمين فينجيهم.","12:7":"تنقلب الأشرار ولا يكونون, أما بيت الصديقين فيثبت.","16:10":"في شفتي الملك وحي. في القضاء فمه لا يخون.","16:11":"قبان الحق وموازينه للرب. كل معايير الكيس عمله.","16:12":"مكرهة الملوك فعل الشر, لأن الكرسي يثبت بالبر.","16:13":"مرضاة الملوك شفتا حق, والمتكلم بالمستقيمات يحب.","16:14":"غضب الملك رسل الموت, والإنسان الحكيم يستعطفه.","16:15":"في نور وجه الملك حياة, ورضاه كسحاب المطر المتأخر.","16:16":"قنية الحكمة كم هي خير من الذهب, وقنية الفهم تختار على الفضة!","16:17":"منهج المستقيمين الحيدان عن الشر. حافظ نفسه حافظ طريقه.","16:18":"قبل الكسر الكبرياء, وقبل السقوط تشامخ الروح.","16:19":"تواضع الروح مع الودعاء خير من قسم الغنيمة مع المتكبرين.","16:20":"الفطن من جهة أمر يجد خيرا, ومن يتكل على الرب فطوبى له.","16:21":"حكيم القلب يدعى فهيما, وحلاوة الشفتين تزيد علما.","16:22":"الفطنة ينبوع حياة لصاحبها, وتأديب الحمقى حماقة.","16:23":"قلب الحكيم يرشد فمه ويزيد شفتيه علما.","16:24":"الكلام الحسن شهد عسل, حلو للنفس وشفاء للعظام.","16:25":"توجد طريق تظهر للإنسان مستقيمة وعاقبتها طرق الموت.","16:26":"نفس التعب تتعب له, لأن فمه يحثه.","16:27":"الرجل اللئيم ينبش الشر, وعلى شفتيه كالنار المتقدة.","16:28":"رجل الأكاذيب يطلق الخصومة, والنمام يفرق الأصدقاء.","16:29":"الرجل الظالم يغوي صاحبه ويسوقه إلى طريق غير صالحة.","16:30":"من يغمض عينيه ليفكر في الأكاذيب, ومن يعض شفتيه, فقد أكمل شرا.","16:31":"تاج جمال: شيبة توجد في طريق البر.","16:32":"البطيء الغضب خير من الجبار, ومالك روحه خير ممن يأخذ مدينة.","16:33":"القرعة تلقى في الحضن, ومن الرب كل حكمها.","17:1":"لقمة يابسة ومعها سلامة, خير من بيت ملآن ذبائح مع خصام.","17:2":"العبد الفطن يتسلط على الابن المخزي ويقاسم الإخوة الميراث.","17:3":"البوطة للفضة, والكور للذهب, وممتحن القلوب الرب.","17:4":"الفاعل الشر يصغي إلى شفة الإثم, والكاذب يأذن للسان فساد.","17:5":"المستهزئ بالفقير يعير خالقه. الفرحان ببلية لا يتبرأ.","17:6":"تاج الشيوخ بنو البنين, وفخر البنين آباؤهم.","17:7":"لا تليق بالأحمق شفة السودد. كم بالأحرى شفة الكذب بالشريف!","17:8":"الهدية حجر كريم في عيني قابلها, حيثما تتوجه تفلح.","17:9":"من يستر معصية يطلب المحبة, ومن يكرر أمرا يفرق بين الأصدقاء.","17:10":"الانتهار يؤثر في الحكيم أكثر من مئة جلدة في الجاهل.","17:11":"الشرير إنما يطلب التمرد فيطلق عليه رسول قاس.","17:12":"ليصادف الإنسان دبة ثكول ولا جاهل في حماقته.","17:13":"من يجازي عن خير بشر لن يبرح الشر من بيته.","17:14":"ابتداء الخصام إطلاق الماء, فقبل أن تدفق المخاصمة اتركها.","17:15":"مبرئ المذنب ومذنب البريء كلاهما مكرهة الرب.","17:16":"لماذا في يد الجاهل ثمن؟ هل لاقتناء الحكمة وليس له فهم؟","17:17":"الصديق يحب في كل وقت, أما الأخ فللشدة يولد.","17:18":"الإنسان الناقص الفهم يصفق كفا ويضمن صاحبه ضمانا.","17:19":"محب المعصية محب الخصام. المعلي بابه يطلب الكسر.","17:20":"الملتوي القلب لا يجد خيرا, والمتقلب اللسان يقع في السوء.","17:21":"من يلد جاهلا فلحزنه, ولا يفرح أبو الأحمق.","17:22":"القلب الفرحان يطيب الجسم, والروح المنسحقة تجفف العظم.","17:23":"الشرير يأخذ الرشوة من الحضن ليعوج طرق القضاء.","17:24":"الحكمة عند الفهيم, وعينا الجاهل في أقصى الأرض.","17:25":"الابن الجاهل غم لأبيه, ومرارة للتي ولدته.","17:26":"أيضا تغريم البريء ليس بحسن, وكذلك ضرب الشرفاء لأجل الاستقامة.","17:27":"ذو المعرفة يبقي كلامه, وذو الفهم وقور الروح.","17:28":"بل الأحمق إذا سكت يحسب حكيما, ومن ضم شفتيه فهيما!","18:1":"المعتزل يطلب شهوته. بكل مشورة يغتاظ.","18:2":"الجاهل لا يسر بالفهم, بل بكشف قلبه.","18:3":"إذا جاء الشرير جاء الاحتقار أيضا, ومع الهوان عار.","18:4":"كلمات فم الإنسان مياه عميقة. نبع الحكمة نهر مندفق.","18:5":"رفع وجه الشرير ليس حسنا لإخطاء الصديق في القضاء.","18:6":"شفتا الجاهل تداخلان في الخصومة, وفمه يدعو بضربات.","18:7":"فم الجاهل مهلكة له, وشفتاه شرك لنفسه.","18:8":"كلام النمام مثل لقم حلوة وهو ينزل إلى مخادع البطن.","18:9":"أيضا المتراخي في عمله هو أخو المسرف.","18:10":"اسم الرب برج حصين, يركض إليه الصديق ويتمنع.","18:11":"ثروة الغني مدينته الحصينة, ومثل سور عال في تصوره.","18:12":"قبل الكسر يتكبر قلب الإنسان, وقبل الكرامة التواضع.","18:13":"من يجيب عن أمر قبل أن يسمعه, فله حماقة وعار.","18:14":"روح الإنسان تحتمل مرضه, أما الروح المكسورة فمن يحملها؟","18:15":"قلب الفهيم يقتني معرفة, وأذن الحكماء تطلب علما.","18:16":"هدية الإنسان ترحب له وتهديه إلى أمام العظماء.","18:17":"الأول في دعواه محق, فيأتي رفيقه ويفحصه.","18:18":"القرعة تبطل الخصومات وتفصل بين الأقوياء.","18:19":"الأخ أمنع من مدينة حصينة, والمخاصمات كعارضة قلعة.","18:20":"من ثمر فم الإنسان يشبع بطنه, من غلة شفتيه يشبع.","18:21":"الموت والحياة في يد اللسان, وأحباؤه يأكلون ثمره.","18:22":"من يجد زوجة يجد خيرا وينال رضى من الرب.","18:23":"بتضرعات يتكلم الفقير, والغني يجاوب بخشونة.","18:24":"المكثر الأصحاب يخرب نفسه, ولكن يوجد محب ألزق من الأخ.","19:1":"الفقير السالك بكماله خير من ملتوي الشفتين وهو جاهل.","19:2":"أيضا كون النفس بلا معرفة ليس حسنا, والمستعجل برجليه يخطئ.","19:3":"حماقة الرجل تعوج طريقه, وعلى الرب يحنق قلبه.","19:4":"الغنى يكثر الأصحاب, والفقير منفصل عن قريبه.","19:5":"شاهد الزور لا يتبرأ, والمتكلم بالأكاذيب لا ينجو.","19:6":"كثيرون يستعطفون وجه الشريف, وكل صاحب لذي العطايا.","19:7":"كل إخوة الفقير يبغضونه, فكم بالحري أصدقاؤه يبتعدون عنه! من يتبع أقوالا فهي له.","19:8":"المقتني الحكمة يحب نفسه. الحافظ الفهم يجد خيرا.","19:9":"شاهد الزور لا يتبرأ, والمتكلم بالأكاذيب يهلك.","19:10":"التنعم لا يليق بالجاهل. كم بالأولى لا يليق بالعبد أن يتسلط على الرؤساء!","19:11":"تعقل الإنسان يبطئ غضبه, وفخره الصفح عن معصية.","19:12":"كزمجرة الأسد حنق الملك, وكالطل على العشب رضوانه.","19:13":"الابن الجاهل مصيبة على أبيه, ومخاصمات الزوجة كالوكف المتتابع.","19:14":"البيت والثروة ميراث من الآباء, أما الزوجة المتعقلة فمن عند الرب.","19:15":"الكسل يلقي في السبات, والنفس المتراخية تجوع.","19:16":"حافظ الوصية حافظ نفسه, والمتهاون بطرقه يموت.","19:17":"من يرحم الفقير يقرض الرب, وعن معروفه يجازيه.","19:18":"أدب ابنك لأن فيه رجاء, ولكن على إماتته لا تحمل نفسك.","19:19":"الشديد الغضب يحمل عقوبة, لأنك إذا نجيته فبعد تعيد.","19:20":"اسمع المشورة واقبل التأديب, لكي تكون حكيما في آخرتك.","19:21":"في قلب الإنسان أفكار كثيرة, لكن مشورة الرب هي تثبت.","19:22":"زينة الإنسان معروفه, والفقير خير من الكذوب.","19:23":"مخافة الرب للحياة. يبيت شبعان لا يتعهده شر.","19:24":"الكسلان يخفي يده في الصحفة, وأيضا إلى فمه لا يردها.","19:25":"اضرب المستهزئ فيتذكى الأحمق, ووبخ فهيما فيفهم معرفة.","19:26":"المخرب أباه والطارد أمه هو ابن مخز ومخجل.","19:27":"كف يا ابني عن استماع التعليم للضلالة عن كلام المعرفة.","19:28":"الشاهد اللئيم يستهزئ بالحق, وفم الأشرار يبلع الإثم.","19:29":"القصاص معد للمستهزئين, والضرب لظهر الجهال.","20:1":"الخمر مستهزئة. المسكر عجاج, ومن يترنح بهما فليس بحكيم.","20:2":"رعب الملك كزمجرة الأسد. الذي يغيظه يخطئ إلى نفسه.","20:3":"مجد الرجل أن يبتعد عن الخصام, وكل أحمق ينازع.","20:4":"الكسلان لا يحرث بسبب الشتاء, فيستعطي في الحصاد ولا يعطى.","20:5":"المشورة في قلب الرجل مياه عميقة, وذو الفطنة يستقيها.","20:6":"أكثر الناس ينادون كل واحد بصلاحه, أما الرجل الأمين فمن يجده؟","20:7":"الصديق يسلك بكماله. طوبى لبنيه بعده.","20:8":"الملك الجالس على كرسي القضاء يذري بعينه كل شر.","20:9":"من يقول: «إني زكيت قلبي, تطهرت من خطيتي؟»","20:10":"معيار فمعيار, مكيال فمكيال, كلاهما مكرهة عند الرب.","20:11":"الولد أيضا يعرف بأفعاله, هل عمله نقي ومستقيم؟","20:12":"الأذن السامعة والعين الباصرة, الرب صنعهما كلتيهما.","20:13":"لا تحب النوم لئلا تفتقر. افتح عينيك تشبع خبزا.","20:14":"«رديء, رديء» يقول المشتري, وإذا ذهب فحينئذ يفتخر!","20:15":"يوجد ذهب وكثرة لآلئ, أما شفاه المعرفة فمتاع ثمين.","20:16":"خذ ثوبه لأنه ضمن غريبا, ولأجل الأجانب ارتهن منه.","20:17":"خبز الكذب لذيذ للإنسان, ومن بعد يمتلئ فمه حصى.","20:18":"المقاصد تثبت بالمشورة, وبالتدابير اعمل حربا.","20:19":"الساعي بالوشاية يفشي السر, فلا تخالط المفتح شفتيه.","20:20":"من سب أباه أو أمه ينطفئ سراجه في حدقة الظلام.","20:21":"رب ملك معجل في أوله, أما آخرته فلا تبارك.","20:22":"لا تقل: «إني أجازي شرا». انتظر الرب فيخلصك.","20:23":"معيار فمعيار مكرهة الرب, وموازين الغش غير صالحة.","20:24":"من الرب خطوات الرجل. أما الإنسان فكيف يفهم طريقه؟","20:25":"هو شرك للإنسان أن يلغو قائلا: «مقدس». وبعد النذر أن يسأل!","20:26":"الملك الحكيم يشتت الأشرار, ويرد عليهم النورج.","20:27":"نفس الإنسان سراج الرب, يفتش كل مخادع البطن.","20:28":"الرحمة والحق يحفظان الملك, وكرسيه يسند بالرحمة.","20:29":"فخر الشبان قوتهم, وبهاء الشيوخ الشيب.","20:30":"حبر جرح منقية للشرير, وضربات بالغة مخادع البطن.","21:1":"قلب الملك في يد الرب كجداول مياه, حيثما شاء يميله.","21:2":"كل طرق الإنسان مستقيمة في عينيه, والرب وازن القلوب.","21:3":"فعل العدل والحق أفضل عند الرب من الذبيحة.","21:4":"طموح العينين وانتفاخ القلب, نور الأشرار خطية.","21:5":"أفكار المجتهد إنما هي للخصب, وكل عجول إنما هو للعوز.","21:6":"جمع الكنوز بلسان كاذب, هو بخار مطرود لطالبي الموت.","21:7":"اغتصاب الأشرار يجرفهم, لأنهم أبوا إجراء العدل.","21:8":"طريق رجل موزور هي ملتوية, أما الزكي فعمله مستقيم.","21:9":"السكنى في زاوية السطح, خير من امرأة مخاصمة وبيت مشترك.","21:10":"نفس الشرير تشتهي الشر. قريبه لا يجد نعمة في عينيه.","21:11":"بمعاقبة المستهزئ يصير الأحمق حكيما, والحكيم بالإرشاد يقبل معرفة.","21:12":"البار يتأمل بيت الشرير ويقلب الأشرار في الشر.","21:13":"من يسد أذنيه عن صراخ المسكين, فهو أيضا يصرخ ولا يستجاب.","21:14":"الهدية في الخفاء تفثأ الغضب, والرشوة في الحضن تفثأ السخط الشديد.","21:15":"إجراء الحق فرح للصديق, والهلاك لفاعلي الإثم.","21:16":"الرجل الضال عن طريق المعرفة يسكن بين جماعة الأخيلة.","21:17":"محب الفرح إنسان معوز. محب الخمر والدهن لا يستغني.","21:18":"الشرير فدية الصديق, ومكان المستقيمين الغادر.","21:19":"السكنى في أرض برية خير من امرأة مخاصمة حردة.","21:20":"كنز مشتهى وزيت في بيت الحكيم, أما الرجل الجاهل فيتلفه.","21:21":"التابع العدل والرحمة يجد حياة, حظا وكرامة.","21:22":"الحكيم يتسور مدينة الجبابرة, ويسقط قوة معتمدها.","21:23":"من يحفظ فمه ولسانه, يحفظ من الضيقات نفسه.","21:24":"المنتفخ المتكبر اسمه «مستهزئ» عامل بفيضان الكبرياء.","21:25":"شهوة الكسلان تقتله, لأن يديه تأبيان الشغل.","21:26":"اليوم كله يشتهي شهوة, أما الصديق فيعطي ولا يمسك.","21:27":"ذبيحة الشرير مكرهة, فكم بالحري حين يقدمها بغش!","21:28":"شاهد الزور يهلك, والرجل السامع للحق يتكلم.","21:29":"الشرير يوقح وجهه, أما المستقيم فيثبت طرقه.","21:30":"ليس حكمة ولا فطنة ولا مشورة تجاه الرب.","21:31":"الفرس معد ليوم الحرب, أما النصرة فمن الرب.","22:1":"الصيت أفضل من الغنى العظيم, والنعمة الصالحة أفضل من الفضة والذهب.","22:2":"الغني والفقير يتلاقيان. صانعهما كليهما الرب.","22:3":"الذكي يبصر الشر فيتوارى, والحمقى يعبرون فيعاقبون.","22:4":"ثواب التواضع ومخافة الرب هو غنى وكرامة وحياة.","22:5":"شوك وفخوخ في طريق الملتوي. من يحفظ نفسه يبتعد عنها.","22:6":"رب الولد في طريقه, فمتى شاخ أيضا لا يحيد عنه.","22:7":"الغني يتسلط على الفقير, والمقترض عبد للمقرض.","22:8":"الزارع إثما يحصد بلية, وعصا سخطه تفنى.","22:9":"الصالح العين هو يبارك, لأنه يعطي من خبزه للفقير.","22:10":"أطرد المستهزئ فيخرج الخصام, ويبطل النزاع والخزي.","22:11":"من أحب طهارة القلب, فلنعمة شفتيه يكون الملك صديقه.","22:12":"عينا الرب تحفظان المعرفة, وهو يقلب كلام الغادرين.","22:13":"قال الكسلان: «الأسد في الخارج, فأقتل في الشوارع!»","22:14":"فم الأجنبيات هوة عميقة. ممقوت الرب يسقط فيها.","22:15":"الجهالة مرتبطة بقلب الولد. عصا التأديب تبعدها عنه.","22:16":"ظالم الفقير تكثيرا لما له, ومعطي الغني, إنما هما للعوز.","22:17":"أمل أذنك واسمع كلام الحكماء, ووجه قلبك إلى معرفتي","22:18":"لأنه حسن إن حفظتها في جوفك, إن تتثبت جميعا على شفتيك.","22:19":"ليكون اتكالك على الرب, عرفتك أنت اليوم.","22:20":"ألم أكتب لك أمورا شريفة من جهة مؤامرة ومعرفة","22:21":"لأعلمك قسط كلام الحق, لترد جواب الحق للذين أرسلوك؟","22:22":"لا تسلب الفقير لكونه فقيرا, ولا تسحق المسكين في الباب","22:23":"لأن الرب يقيم دعواهم, ويسلب سالبي أنفسهم.","22:24":"لا تستصحب غضوبا ومع رجل ساخط لا تجئ","22:25":"لئلا تألف طرقه, وتأخذ شركا إلى نفسك.","22:26":"لا تكن من صافقي الكف, ولا من ضامني الديون.","22:27":"إن لم يكن لك ما تفي, فلماذا يأخذ فراشك من تحتك؟","22:28":"لا تنقل التخم القديم الذي وضعه آباؤك.","22:29":"أرأيت رجلا مجتهدا في عمله؟ أمام الملوك يقف. لا يقف أمام الرعاع!","23:1":"إذا جلست تأكل مع متسلط, فتأمل ما هو أمامك تأملا","23:2":"وضع سكينا لحنجرتك إن كنت شرها!","23:3":"لا تشته أطايبه لأنها خبز أكاذيب.","23:4":"لا تتعب لكي تصير غنيا. كف عن فطنتك.","23:5":"هل تطير عينيك نحوه وليس هو؟ لأنه إنما يصنع لنفسه أجنحة. كالنسر يطير نحو السماء.","23:6":"لا تأكل خبز ذي عين شريرة, ولا تشته أطايبه.","23:7":"لأنه كما شعر في نفسه هكذا هو. يقول لك: «كل واشرب» وقلبه ليس معك.","23:8":"اللقمة التي أكلتها تتقيأها, وتخسر كلماتك الحلوة.","23:9":"في أذني جاهل لا تتكلم لأنه يحتقر حكمة كلامك.","23:10":"لا تنقل التخم القديم, ولا تدخل حقول الأيتام","23:11":"لأن وليهم قوي. هو يقيم دعواهم عليك.","23:12":"وجه قلبك إلى الأدب, وأذنيك إلى كلمات المعرفة.","23:13":"لا تمنع التأديب عن الولد, لأنك إن ضربته بعصا لا يموت.","23:14":"تضربه أنت بعصا فتنقذ نفسه من الهاوية.","23:15":"يا ابني, إن كان قلبك حكيما يفرح قلبي أنا أيضا","23:16":"وتبتهج كليتاي إذا تكلمت شفتاك بالمستقيمات.","23:17":"لا يحسدن قلبك الخاطئين, بل كن في مخافة الرب اليوم كله.","23:18":"لأنه لا بد من ثواب, ورجاؤك لا يخيب.","23:19":"اسمع أنت يا ابني, وكن حكيما, وأرشد قلبك في الطريق.","23:20":"لا تكن بين شريبي الخمر, بين المتلفين أجسادهم","23:21":"لأن السكير والمسرف يفتقران, والنوم يكسو الخرق.","23:22":"اسمع لأبيك الذي ولدك, ولا تحتقر أمك إذا شاخت.","23:23":"اقتن الحق ولا تبعه, والحكمة والأدب والفهم.","23:24":"أبو الصديق يبتهج ابتهاجا, ومن ولد حكيما يسر به.","23:25":"يفرح أبوك وأمك, وتبتهج التي ولدتك.","23:26":"يا ابني أعطني قلبك, ولتلاحظ عيناك طرقي.","23:27":"لأن الزانية هوة عميقة, والأجنبية حفرة ضيقة.","23:28":"هي أيضا كلص تكمن وتزيد الغادرين بين الناس.","23:29":"لمن الويل؟ لمن الشقاوة؟ لمن المخاصمات؟ لمن الكرب لمن الجروح بلا سبب؟ لمن ازمهرار العينين؟","23:30":"للذين يدمنون الخمر, الذين يدخلون في طلب الشراب الممزوج.","23:31":"لا تنظر إلى الخمر إذا احمرت حين تظهر حبابها في الكأس وساغت مرقرقة.","23:32":"في الآخر تلسع كالحية وتلدغ كالأفعوان.","23:33":"عيناك تنظران الأجنبيات, وقلبك ينطق بأمور ملتوية.","23:34":"وتكون كمضطجع في قلب البحر, أو كمضطجع على رأس سارية.","23:35":"يقول: «ضربوني ولم أتوجع. لقد لكأوني ولم أعرف. متى أستيقظ أعود أطلبها بعد!»","24:1":"لا تحسد أهل الشر, ولا تشته أن تكون معهم","24:2":"لأن قلبهم يلهج بالاغتصاب, وشفاههم تتكلم بالمشقة.","24:3":"بالحكمة يبنى البيت وبالفهم يثبت","24:4":"وبالمعرفة تمتلئ المخادع من كل ثروة كريمة ونفيسة.","24:5":"الرجل الحكيم في عز, وذو المعرفة متشدد القوة.","24:6":"لأنك بالتدابير تعمل حربك, والخلاص بكثرة المشيرين.","24:7":"الحكم عالية عن الأحمق. لا يفتح فمه في الباب.","24:8":"المتفكر في عمل الشر يدعى مفسدا.","24:9":"فكر الحماقة خطية, ومكرهة الناس المستهزئ.","24:10":"إن ارتخيت في يوم الضيق ضاقت قوتك.","24:11":"أنقذ المنقادين إلى الموت, والممدودين للقتل. لا تمتنع.","24:12":"إن قلت: «هوذا لم نعرف هذا» - أفلا يفهم وازن القلوب وحافظ نفسك ألا يعلم؟ فيرد على الإنسان مثل عمله.","24:13":"يا ابني, كل عسلا لأنه طيب, وقطر العسل حلو في حنكك.","24:14":"كذلك معرفة الحكمة لنفسك. إذا وجدتها فلا بد من ثواب, ورجاؤك لا يخيب.","24:15":"لا تكمن أيها الشرير لمسكن الصديق. لا تخرب ربعه.","24:16":"لأن الصديق يسقط سبع مرات ويقوم. أما الأشرار فيعثرون بالشر.","24:17":"لا تفرح بسقوط عدوك, ولا يبتهج قلبك إذا عثر","24:18":"لئلا يرى الرب ويسوء ذلك في عينيه, فيرد عنه غضبه.","24:19":"لا تغر من الأشرار ولا تحسد الأثمة.","24:20":"لأنه لا يكون ثواب للأشرار. سراج الأثمة ينطفئ.","24:21":"يا ابني, اخش الرب والملك. لا تخالط المتقلبين","24:22":"لأن بليتهم تقوم بغتة, ومن يعلم بلاءهما كليهما.","24:23":"هذه أيضا للحكماء: محاباة الوجوه في الحكم ليست صالحة.","24:24":"من يقول للشرير: «أنت صديق» تسبه العامة. تلعنه الشعوب.","24:25":"أما الذين يؤدبون فينعمون, وبركة خير تأتي عليهم.","24:26":"تقبل شفتا من يجاوب بكلام مستقيم.","24:27":"هيئ عملك في الخارج وأعده في حقلك. بعد تبني بيتك.","24:28":"لا تكن شاهدا على قريبك بلا سبب, فهل تخادع بشفتيك؟","24:29":"لا تقل: «كما فعل بي هكذا أفعل به. أرد على الإنسان مثل عمله».","24:30":"عبرت بحقل الكسلان وبكرم الرجل الناقص الفهم","24:31":"فإذا هو قد علاه كله القريص, وقد غطى العوسج وجهه, وجدار حجارته انهدم.","24:32":"ثم نظرت ووجهت قلبي. رأيت وقبلت تعليما.","24:33":"نوم قليل بعد نعاس قليل, وطي اليدين قليلا للرقود","24:34":"فيأتي فقرك كعداء وعوزك كغاز!","25:1":"هذه أيضا أمثال سليمان التي نقلها رجال حزقيا ملك يهوذا:","25:2":"مجد الله إخفاء الأمر, ومجد الملوك فحص الأمر.","25:3":"السماء للعلو, والأرض للعمق, وقلوب الملوك لا تفحص.","25:4":"أزل الزغل من الفضة, فيخرج إناء للصائغ.","25:5":"أزل الشرير من قدام الملك, فيثبت كرسيه بالعدل.","25:6":"لا تتفاخر أمام الملك, ولا تقف في مكان العظماء","25:7":"لأنه خير أن يقال لك ارتفع إلى هنا, من أن تحط في حضرة الرئيس الذي رأته عيناك.","25:8":"لا تبرز عاجلا إلى الخصام, لئلا تفعل شيئا في الآخر حين يخزيك قريبك.","25:9":"أقم دعواك مع قريبك, ولا تبح بسر غيرك","25:10":"لئلا يعيرك السامع, فلا تنصرف فضيحتك.","25:11":"تفاح من ذهب في مصوغ من فضة, كلمة مقولة في محلها.","25:12":"قرط من ذهب وحلي من إبريز, الموبخ الحكيم لأذن سامعة.","25:13":"كبرد الثلج في يوم الحصاد, الرسول الأمين لمرسليه, لأنه يرد نفس سادته.","25:14":"سحاب وريح بلا مطر, الرجل المفتخر بهدية كذب.","25:15":"ببطء الغضب يقنع الرئيس, واللسان اللين يكسر العظم.","25:16":"أوجدت عسلا؟ فكل كفايتك, لئلا تتخم فتتقيأه.","25:17":"اجعل رجلك عزيزة في بيت قريبك, لئلا يمل منك فيبغضك.","25:18":"مقمعة وسيف وسهم حاد, الرجل المجيب قريبه بشهادة زور.","25:19":"سن مهتومة ورجل مخلعة, الثقة بالخائن في يوم الضيق.","25:20":"كنزع الثوب في يوم البرد, كخل على نطرون, من يغني أغاني لقلب كئيب.","25:21":"إن جاع عدوك فأطعمه خبزا, وإن عطش فاسقه ماء","25:22":"فإنك تجمع جمرا على رأسه, والرب يجازيك.","25:23":"ريح الشمال تطرد المطر, والوجه المعبس يطرد لسانا ثالبا.","25:24":"السكنى في زاوية السطح, خير من امرأة مخاصمة في بيت مشترك.","25:25":"مياه باردة لنفس عطشانة, الخبر الطيب من أرض بعيدة.","25:26":"عين مكدرة وينبوع فاسد, الصديق المنحني أمام الشرير.","25:27":"أكل كثير من العسل ليس بحسن, وطلب الناس مجد أنفسهم ثقيل.","25:28":"مدينة منهدمة بلا سور, الرجل الذي ليس له سلطان على روحه.","26:1":"كالثلج في الصيف وكالمطر في الحصاد, هكذا الكرامة غير لائقة بالجاهل.","26:2":"كالعصفور للفرار وكالسنونة للطيران, كذلك لعنة بلا سبب لا تأتي.","26:3":"السوط للفرس واللجام للحمار, والعصا لظهر الجهال.","26:4":"لا تجاوب الجاهل حسب حماقته لئلا تعدله أنت.","26:5":"جاوب الجاهل حسب حماقته لئلا يكون حكيما في عيني نفسه.","26:6":"يقطع الرجلين, يشرب ظلما, من يرسل كلاما عن يد جاهل.","26:7":"ساقا الأعرج متدلدلتان, وكذا المثل في فم الجهال.","26:8":"كصرة حجارة كريمة في رجمة, هكذا المعطي كرامة للجاهل.","26:9":"شوك مرتفع بيد سكران, مثل المثل في فم الجهال.","26:10":"رام يطعن الكل, هكذا من يستأجر الجاهل أو يستأجر المحتالين.","26:11":"كما يعود الكلب إلى قيئه, هكذا الجاهل يعيد حماقته.","26:12":"أرأيت رجلا حكيما في عيني نفسه؟ الرجاء بالجاهل أكثر من الرجاء به!","26:13":"قال الكسلان: «الأسد في الطريق, الشبل في الشوارع».","26:14":"الباب يدور على صائره, والكسلان على فراشه.","26:15":"الكسلان يخفي يده في الصحفة, ويشق عليه أن يردها إلى فمه.","26:16":"الكسلان أوفر حكمة في عيني نفسه من السبعة المجيبين بعقل.","26:17":"كممسك أذني كلب, هكذا من يعبر ويتعرض لمشاجرة لا تعنيه.","26:18":"مثل المجنون الذي يرمي نارا وسهاما وموتا","26:19":"هكذا الرجل الخادع قريبه ويقول: «ألم ألعب أنا!»","26:20":"بعدم الحطب تنطفئ النار, وحيث لا نمام يهدأ الخصام.","26:21":"فحم للجمر وحطب للنار, هكذا الرجل المخاصم لتهييج النزاع.","26:22":"كلام النمام مثل لقم حلوة فينزل إلى مخادع البطن.","26:23":"فضة زغل تغشي شقفة, هكذا الشفتان المتوقدتان والقلب الشرير.","26:24":"بشفتيه يتنكر المبغض, وفي جوفه يضع غشا.","26:25":"إذا حسن صوته فلا تأتمنه, لأن في قلبه سبع رجاسات.","26:26":"من يغطي بغضة بمكر, يكشف خبثه بين الجماعة.","26:27":"من يحفر حفرة يسقط فيها, ومن يدحرج حجرا يرجع عليه.","26:28":"اللسان الكاذب يبغض منسحقيه, والفم الملق يعد خرابا.","27:1":"لا تفتخر بالغد لأنك لا تعلم ماذا يلده يوم.","27:2":"ليمدحك الغريب لا فمك, الأجنبي لا شفتاك.","27:3":"الحجر ثقيل والرمل ثقيل, وغضب الجاهل أثقل منهما كليهما.","27:4":"الغضب قساوة والسخط جراف, ومن يقف قدام الحسد؟","27:5":"التوبيخ الظاهر خير من الحب المستتر.","27:6":"أمينة هي جروح المحب, وغاشة هي قبلات العدو.","27:7":"النفس الشبعانة تدوس العسل, وللنفس الجائعة كل مر حلو.","27:8":"مثل العصفور التائه من عشه, هكذا الرجل التائه من مكانه.","27:9":"الدهن والبخور يفرحان القلب, وحلاوة الصديق من مشورة النفس.","27:10":"لا تترك صديقك وصديق أبيك, ولا تدخل بيت أخيك في يوم بليتك. الجار القريب خير من الأخ البعيد.","27:11":"يا ابني, كن حكيما وفرح قلبي, فأجيب من يعيرني كلمة.","27:12":"الذكي يبصر الشر فيتوارى. الأغبياء يعبرون فيعاقبون.","27:13":"خذ ثوبه لأنه ضمن غريبا, ولأجل الأجانب ارتهن منه.","27:14":"من يبارك قريبه بصوت عال في الصباح باكرا, يحسب له لعنا.","27:15":"الوكف المتتابع في يوم ممطر, والمرأة المخاصمة سيان","27:16":"من يخبئها يخبئ الريح ويمينه تقبض على زيت!","27:17":"الحديد بالحديد يحدد, والإنسان يحدد وجه صاحبه.","27:18":"من يحمي تينة يأكل ثمرتها, وحافظ سيده يكرم.","27:19":"كما في الماء الوجه للوجه, كذلك قلب الإنسان للإنسان.","27:20":"الهاوية والهلاك لا يشبعان, وكذا عينا الإنسان لا تشبعان.","27:21":"البوطة للفضة والكور للذهب, كذا الإنسان لفم مادحه.","27:22":"إن دققت الأحمق في هاون بين السميذ بمدق, لا تبرح عنه حماقته.","27:23":"معرفة اعرف حال غنمك, واجعل قلبك إلى قطعانك","27:24":"لأن الغنى ليس بدائم, ولا التاج لدور فدور.","27:25":"فني الحشيش وظهر العشب واجتمع نبات الجبال.","27:26":"الحملان للباسك, وثمن حقل أعتدة.","27:27":"وكفاية من لبن المعز لطعامك, لقوت بيتك ومعيشة فتياتك.","28:1":"الشرير يهرب ولا طارد, أما الصديقون فكشبل ثبيت.","28:2":"لمعصية أرض تكثر رؤساؤها, لكن بذي فهم ومعرفة تدوم.","28:3":"الرجل الفقير الذي يظلم فقراء, هو مطر جارف لا يبقي طعاما.","28:4":"تاركو الشريعة يمدحون الأشرار, وحافظو الشريعة يخاصمونهم.","28:5":"الناس الأشرار لا يفهمون الحق, وطالبو الرب يفهمون كل شيء.","28:6":"الفقير السالك باستقامته, خير من معوج الطرق وهو غني.","28:7":"الحافظ الشريعة هو ابن فهيم, وصاحب المسرفين يخجل أباه.","28:8":"المكثر ماله بالربا والمرابحة, فلمن يرحم الفقراء يجمعه!","28:9":"من يحول أذنه عن سماع الشريعة, فصلاته أيضا مكرهة.","28:10":"من يضل المستقيمين في طريق رديئة ففي حفرته يسقط هو. أما الكملة فيمتلكون خيرا.","28:11":"الرجل الغني حكيم في عيني نفسه, والفقير الفهيم يفحصه.","28:12":"إذا فرح الصديقون عظم الفخر, وعند قيام الأشرار تختفي الناس.","28:13":"من يكتم خطاياه لا ينجح, ومن يقر بها ويتركها يرحم.","28:14":"طوبى للإنسان المتقي دائما, أما المقسي قلبه فيسقط في الشر.","28:15":"أسد زائر ودب ثائر, المتسلط الشرير على شعب فقير.","28:16":"رئيس ناقص الفهم وكثير المظالم. مبغض الرشوة تطول أيامه.","28:17":"الرجل المثقل بدم نفس, يهرب إلى الجب. لا يمسكنه أحد.","28:18":"السالك بالكمال يخلص, والملتوي في طريقين يسقط في إحداهما.","28:19":"المشتغل بأرضه يشبع خبزا, وتابع البطالين يشبع فقرا.","28:20":"الرجل الأمين كثير البركات, والمستعجل إلى الغنى لا يبرأ.","28:21":"محاباة الوجوه ليست صالحة, فيذنب الإنسان لأجل كسرة خبز.","28:22":"ذو العين الشريرة يعجل إلى الغنى, ولا يعلم أن الفقر يأتيه.","28:23":"من يوبخ إنسانا يجد أخيرا نعمة أكثر من المطري باللسان.","28:24":"السالب أباه أو أمه وهو يقول: «لا بأس» فهو رفيق لرجل مخرب.","28:25":"المنتفخ النفس يهيج الخصام, والمتكل على الرب يسمن.","28:26":"المتكل على قلبه هو جاهل, والسالك بحكمة هو ينجو.","28:27":"من يعطي الفقير لا يحتاج, ولمن يحجب عنه عينيه لعنات كثيرة.","28:28":"عند قيام الأشرار تختبئ الناس, وبهلاكهم يكثر الصديقون.","29:1":"الكثير التوبخ, المقسي عنقه, بغتة يكسر ولا شفاء.","29:2":"إذا ساد الصديقون فرح الشعب, وإذا تسلط الشرير يئن الشعب.","29:3":"من يحب الحكمة يفرح أباه, ورفيق الزواني يبدد مالا.","29:4":"الملك بالعدل يثبت الأرض, والقابل الهدايا يدمرها.","29:5":"الرجل الذي يطري صاحبه يبسط شبكة لرجليه.","29:6":"في معصية رجل شرير شرك, أما الصديق فيترنم ويفرح.","29:7":"الصديق يعرف دعوى الفقراء, أما الشرير فلا يفهم معرفة.","29:8":"الناس المستهزئون يفتنون المدينة, أما الحكماء فيصرفون الغضب.","29:9":"رجل حكيم إن حاكم رجلا أحمق, فإن غضب وإن ضحك فلا راحة.","29:10":"أهل الدماء يبغضون الكامل, أما المستقيمون فيسألون عن نفسه.","29:11":"الجاهل يظهر كل غيظه, والحكيم يسكنه أخيرا.","29:12":"الحاكم المصغي إلى كلام كذب كل خدامه أشرار.","29:13":"الفقير والظالم يتلاقيان. الرب ينور أعين كليهما.","29:14":"الملك الحاكم بالحق للفقراء يثبت كرسيه إلى الأبد.","29:15":"العصا والتوبيخ يعطيان حكمة, والصبي المطلق إلى هواه يخجل أمه.","29:16":"إذا ساد الأشرار كثرت المعاصي. أما الصديقون فينظرون سقوطهم.","29:17":"أدب ابنك فيريحك ويعطي نفسك لذات.","29:18":"بلا رؤيا يجمح الشعب, أما حافظ الشريعة فطوباه.","29:19":"بالكلام لا يؤدب العبد, لأنه يفهم ولا يعنى.","29:20":"أرأيت إنسانا عجولا في كلامه؟ الرجاء بالجاهل أكثر من الرجاء به.","29:21":"من دلل عبده من حداثته ففي آخرته يصير منونا.","29:22":"الرجل الغضوب يهيج الخصام, والرجل السخوط كثير المعاصي.","29:23":"كبرياء الإنسان تضعه, والوضيع الروح ينال مجدا.","29:24":"من يقاسم سارقا يبغض نفسه. يسمع اللعن ولا يقر.","29:25":"خشية الإنسان تضع شركا, والمتكل على الرب يرفع.","29:26":"كثيرون يطلبون وجه المتسلط, أما حق الإنسان فمن الرب.","29:27":"الرجل الظالم مكرهة الصديقين, والمستقيم الطريق مكرهة الشرير.","30:1":"كلام أجور ابن متقية مسا. وحي هذا الرجل إلى إيثيئيل. إلى إيثيئيل وأكال:","30:2":"إني أبلد من كل إنسان, وليس لي فهم إنسان","30:3":"ولم أتعلم الحكمة, ولم أعرف معرفة القدوس.","30:4":"من صعد إلى السماوات ونزل؟ من جمع الريح في حفنتيه؟ من صر المياه في ثوب؟ من ثبت جميع أطراف الأرض؟ ما اسمه وما اسم ابنه إن عرفت؟","30:5":"كل كلمة من الله نقية. ترس هو للمحتمين به.","30:6":"لا تزد على كلماته لئلا يوبخك فتكذب.","30:7":"اثنتين سألت منك, فلا تمنعهما عني قبل أن أموت:","30:8":"أبعد عني الباطل والكذب. لا تعطني فقرا ولا غنى. أطعمني خبز فريضتي","30:9":"لئلا أشبع وأكفر وأقول: «من هو الرب؟» أو لئلا أفتقر وأسرق وأتخذ اسم إلهي باطلا.","30:10":"لا تشك عبدا إلى سيده لئلا يلعنك فتأثم.","30:11":"جيل يلعن أباه ولا يبارك أمه","30:12":"جيل طاهر في عيني نفسه, وهو لم يغتسل من قذره","30:13":"جيل ما أرفع عينيه, وحواجبه مرتفعة","30:14":"جيل أسنانه سيوف, وأضراسه سكاكين, لأكل المساكين عن الأرض والفقراء من بين الناس.","30:15":"للعلوقة ابنتان: «هات, هات!» ثلاثة لا تشبع. أربعة لا تقول: «كفا»:","30:16":"الهاوية, والرحم العقيم, وأرض لا تشبع ماء, والنار لا تقول: «كفا».","30:17":"العين المستهزئة بأبيها, والمحتقرة إطاعة أمها, تقورها غربان الوادي, وتأكلها فراخ النسر.","30:18":"ثلاثة عجيبة فوقي, وأربعة لا أعرفها:","30:19":"طريق نسر في السماوات, وطريق حية على صخر, وطريق سفينة في قلب البحر, وطريق رجل بفتاة.","30:20":"كذلك طريق المرأة الزانية. أكلت ومسحت فمها وقالت: «ما عملت إثما!».","30:21":"تحت ثلاثة تضطرب الأرض, وأربعة لا تستطيع احتمالها:","30:22":"تحت عبد إذا ملك, وأحمق إذا شبع خبزا.","30:23":"تحت شنيعة إذا تزوجت, وأمة إذا ورثت سيدتها.","30:24":"أربعة هي الأصغر في الأرض, ولكنها حكيمة جدا:","30:25":"النمل طائفة غير قوية, ولكنه يعد طعامه في الصيف.","30:26":"الوبار طائفة ضعيفة, ولكنها تضع بيوتها في الصخر.","30:27":"الجراد ليس له ملك, ولكنه يخرج كله فرقا فرقا.","30:28":"العنكبوت تمسك بيديها, وهي في قصور الملوك.","30:29":"ثلاثة هي حسنة التخطي, وأربعة مشيها مستحسن:","30:30":"الأسد جبار الوحوش, ولا يرجع من قدام أحد","30:31":"ضامر الشاكلة, والتيس, والملك الذي لا يقاوم.","30:32":"إن حمقت بالترفع وإن تآمرت, فضع يدك على فمك.","30:33":"لأن عصر اللبن يخرج جبنا, وعصر الأنف يخرج دما, وعصر الغضب يخرج خصاما.","31:1":"كلام لموئيل ملك مسا. علمته إياه أمه:","31:2":"ماذا يا ابني ثم ماذا يا ابن رحمي ثم ماذا يا ابن نذوري؟ -","31:3":"لا تعط حيلك للنساء, ولا طرقك لمهلكات الملوك.","31:4":"ليس للملوك يا لموئيل, ليس للملوك أن يشربوا خمرا, ولا للعظماء المسكر.","31:5":"لئلا يشربوا وينسوا المفروض, ويغيروا حجة كل بني المذلة.","31:6":"أعطوا مسكرا لهالك, وخمرا لمري النفس.","31:7":"يشرب وينسى فقره, ولا يذكر تعبه بعد.","31:8":"افتح فمك لأجل الأخرس في دعوى كل يتيم.","31:9":"افتح فمك. اقض بالعدل وحام عن الفقير والمسكين.","31:10":"امرأة فاضلة من يجدها؟ لأن ثمنها يفوق اللآلئ.","31:11":"بها يثق قلب زوجها فلا يحتاج إلى غنيمة.","31:12":"تصنع له خيرا لا شرا كل أيام حياتها.","31:13":"تطلب صوفا وكتانا وتشتغل بيدين راضيتين.","31:14":"هي كسفن التاجر. تجلب طعامها من بعيد.","31:15":"وتقوم إذ الليل بعد وتعطي أكلا لأهل بيتها وفريضة لفتياتها.","31:16":"تتأمل حقلا فتأخذه, وبثمر يديها تغرس كرما.","31:17":"تنطق حقويها بالقوة وتشدد ذراعيها.","31:18":"تشعر أن تجارتها جيدة. سراجها لا ينطفئ في الليل.","31:19":"تمد يديها إلى المغزل, وتمسك كفاها بالفلكة.","31:20":"تبسط كفيها للفقير, وتمد يديها إلى المسكين.","31:21":"لا تخشى على بيتها من الثلج, لأن كل أهل بيتها لابسون حللا.","31:22":"تعمل لنفسها موشيات. لبسها بوص وأرجوان.","31:23":"زوجها معروف في الأبواب حين يجلس بين مشايخ الأرض.","31:24":"تصنع قمصانا وتبيعها, وتعرض مناطق على الكنعاني.","31:25":"العز والبهاء لباسها, وتضحك على الزمن الآتي.","31:26":"تفتح فمها بالحكمة, وفي لسانها سنة المعروف.","31:27":"تراقب طرق أهل بيتها, ولا تأكل خبز الكسل.","31:28":"يقوم أولادها ويطوبونها. زوجها أيضا فيمدحها.","31:29":"بنات كثيرات عملن فضلا, أما أنت ففقت عليهن جميعا.","31:30":"الحسن غش والجمال باطل, أما المرأة المتقية الرب فهي تمدح.","31:31":"أعطوها من ثمر يديها, ولتمدحها أعمالها في الأبواب."};
